package com.nosferatu.divinemachinerylegacy.gui;import com.nosferatu.divinemachinerylegacy.tile.TileMechanicalDaisy;import net.minecraft.entity.player.EntityPlayer;import net.minecraft.entity.player.InventoryPlayer;import net.minecraft.inventory.*;import net.minecraft.item.ItemStack;
public class ContainerMechanicalDaisy extends Container{private final TileMechanicalDaisy tile;private int lastWater=Integer.MIN_VALUE,clientWater;private static final int[][] P={{90,26},{112,32},{118,54},{112,76},{90,82},{68,76},{62,54},{68,32}};public ContainerMechanicalDaisy(InventoryPlayer p,TileMechanicalDaisy t){tile=t;addSlotToContainer(new Valid(t,0,t.hasUpgradeSlot()?90:-1000,t.hasUpgradeSlot()?54:-1000));for(int i=0;i<8;i++)addSlotToContainer(new Valid(t,1+i,P[i][0],P[i][1]));for(int r=0;r<3;r++)for(int c=0;c<9;c++)addSlotToContainer(new Slot(p,c+r*9+9,28+c*18,148+r*18));for(int c=0;c<9;c++)addSlotToContainer(new Slot(p,c,28+c*18,206));}@Override public boolean canInteractWith(EntityPlayer p){return tile.isUseableByPlayer(p);}@Override public void detectAndSendChanges(){super.detectAndSendChanges();int w=tile.getWater();for(Object o:crafters)if(w!=lastWater){ICrafting c=(ICrafting)o;c.sendProgressBarUpdate(this,0,w&65535);c.sendProgressBarUpdate(this,1,w>>>16);}lastWater=w;}@Override public void updateProgressBar(int id,int v){int u=v&65535;if(id==0)clientWater=(clientWater&0xffff0000)|u;else if(id==1)clientWater=(clientWater&0xffff)|(u<<16);tile.setClientWater(clientWater);}@Override public ItemStack transferStackInSlot(EntityPlayer p,int i){Slot s=(Slot)inventorySlots.get(i);if(s==null||!s.getHasStack())return null;ItemStack st=s.getStack(),orig=st.copy();int machine=9;if(i<machine){if(!mergeItemStack(st,machine,inventorySlots.size(),true))return null;}else{boolean moved=false;for(int q=0;q<machine&&!moved;q++)if(tile.isItemValidForSlot(q,st))moved=mergeItemStack(st,q,q+1,false);if(!moved)return null;}if(st.stackSize==0)s.putStack(null);else s.onSlotChanged();return orig;}private static class Valid extends Slot{Valid(TileMechanicalDaisy t,int i,int x,int y){super(t,i,x,y);}@Override public boolean isItemValid(ItemStack s){return inventory.isItemValidForSlot(getSlotIndex(),s);}@Override public int getSlotStackLimit(){return getSlotIndex()==0?1:((TileMechanicalDaisy)inventory).getSlotLimit();}}}
